export const query = graphql `
query Blogs($id: Int!, $nodeId: String!) {
  article: airtable(table: {eq: "Blogs"}, data: {BlogId: {eq: $id}}) {
    id
    data {
      BlogContent
      BlogDate(formatString: "DD MMM YYYY")
      BlogExcerpt
      BlogTitle
      BlogFeaturedImage {
        thumbnails {
          large {
            height
            url
            width
          }
        }
      }
    }
  }
  attachment: allFile(filter: {id: {}, parent: {id: {eq: $nodeId}}}) {
    edges {
      node {
        publicURL
      }
    }
  }
}
`


const Blog = (props) => {
  /*  
 return(
   <Layout>
     <h1>{props.data.contentfulBlogPost.title}</h1>
     <p>{props.data.contentfulBlogPost.publishedDate}</p>
     <p>{props.data.contentfulBlogPost.body.raw}</p>
   </Layout>
   )
   */
  //console.log(props.data.article.data);
  //const image = getImage(props.data.contentfulBlogPost.body.references[0])
  //const { body } = props.data.contentfulBlogPost
  //console.log(props);

  return (<div>
    <Layout>
      <SEO title={props.data.article.data.BlogTitle} description={props.data.article.data.BlogExcerpt} image={props.data.article.data.BlogFeaturedImage[0].thumbnails.large.url} post={props.data.article.data} />
      <h1>{props.data.article.data.BlogTitle}</h1>
      <div className={blogStyles.share_published}>
        <small>{`Published on ${props.data.article.data.BlogDate}`}</small>
        <ShareButtons title={props.data.article.data.BlogTitle} description={props.data.article.data.BlogExcerpt}></ShareButtons>
      </div>
      <blockquote>{props.data.article.data.BlogExcerpt}</blockquote>
      {/*<img className={blogStyles.BlogImg} src={props.data.article.data.BlogFeaturedImage[0].thumbnails.large.url} alt={`${props.data.article.data.BlogTitle} Image`} />
      */}
      {props.data.attachment.edges[0] &&
      <img className={blogStyles.BlogImg} src={props.data.attachment.edges[0].node.publicURL} alt={`${props.data.article.data.BlogTitle} Image`} />}
      <div>
        {props.pageContext.publicUrl}
      </div>
      <div
        dangerouslySetInnerHTML={{
          __html: unified()
            .use(markdown)
            .use(html)
            .processSync(props.data.article.data.BlogContent)
        }}
      />

      <div className={blogStyles.readMore}>
        <span>Read More Blogs</span>
        <ul className={blogStyles.blogNav}>
          <li><Link to={props.pageContext.prev.slug ? `/blog/${props.pageContext.prev.slug}-${props.pageContext.prev.id}` : ""}>{props.pageContext.prev.slug ? props.pageContext.prev.title : ""}</Link></li>
          <li><Link to={props.pageContext.next.slug ? `/blog/${props.pageContext.next.slug}-${props.pageContext.next.id}` : ""}>{props.pageContext.next.slug ? props.pageContext.next.title : ""}</Link></li>
        </ul>
      </div>
      <DisqusComment title={props.data.article.data.BlogTitle} />

    </Layout>

  </div>)
}

export default Blog