import React from 'react'
import { Facebook, Twitter, Linkedin, Pocket } from 'react-feather';
import {
  FacebookShareButton,
  LinkedinShareButton,
  TwitterShareButton,
} from 'react-share';
import { useLocation } from '@reach/router';
import { graphql, useStaticQuery} from 'gatsby';
import * as shareButtonStyles from './share-button.module.scss'


const ShareButtons = ({  title, description }) =>
{

    const { pathname } = useLocation();
    
    const data = useStaticQuery(graphql`
    {
      site {
        siteMetadata {
          siteUrl
          title
          description
          image
          author
        }
      }
    }
    `);
    const defaults = data.site.siteMetadata;
return (
  <div className={shareButtonStyles.post_meta_share_icons}>
    <FacebookShareButton url={defaults.siteUrl + pathname} quote={description}>
      <Facebook strokeWidth={1.25} />
    </FacebookShareButton>

    <LinkedinShareButton url={defaults.siteUrl + pathname} title={title} summary={description}>
      <Linkedin strokeWidth={1.25} />
    </LinkedinShareButton>

    <TwitterShareButton url={defaults.siteUrl + pathname} title={description}>
      <Twitter strokeWidth={1.25} />
    </TwitterShareButton>
  </div>
);
}


export default ShareButtons